-- Bot Cobra Fase 1: CollectionRule + Debt + DebtEvent (CRUD administrativo).
-- Sem WhatsApp/scheduler/PIX/PaymentPromise/CollectionAttempt/DebtPaymentAllocation
-- nesta fase. Sem alteração em Payment/PaymentGatewayCharge.

CREATE TABLE `collection_rules` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `public_id` CHAR(36) NOT NULL, `tenant_id` BIGINT UNSIGNED NOT NULL, `name` VARCHAR(120) NOT NULL, `active` BOOLEAN NOT NULL DEFAULT true, `cadence_type` ENUM('WEEKLY', 'BIWEEKLY', 'MONTHLY', 'CUSTOM_DAYS') NOT NULL, `cadence_days` SMALLINT UNSIGNED NULL, `preferred_weekday` TINYINT UNSIGNED NULL, `monthly_day` TINYINT UNSIGNED NULL, `allowed_start_hour` TINYINT UNSIGNED NOT NULL DEFAULT 9, `allowed_end_hour` TINYINT UNSIGNED NOT NULL DEFAULT 18, `max_attempts_per_day` TINYINT UNSIGNED NOT NULL DEFAULT 1, `consecutive_days` TINYINT UNSIGNED NOT NULL DEFAULT 3, `pause_days_after_cycle` TINYINT UNSIGNED NOT NULL DEFAULT 4, `max_cycles` TINYINT UNSIGNED NULL, `skip_sundays` BOOLEAN NOT NULL DEFAULT true, `partial_payment_enabled` BOOLEAN NOT NULL DEFAULT true, `partial_offer_percentages` JSON NOT NULL, `partial_minimum_cents` BIGINT UNSIGNED NOT NULL DEFAULT 0, `partial_rounding_step_cents` BIGINT UNSIGNED NOT NULL DEFAULT 1, `ask_promise_after_partial_payment` BOOLEAN NOT NULL DEFAULT true, `promise_quick_options_days` JSON NOT NULL, `no_response_followup_next_day` BOOLEAN NOT NULL DEFAULT true, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), UNIQUE INDEX `collection_rules_public_id_key` (`public_id`), INDEX `collection_rules_tenant_id_active_idx` (`tenant_id`, `active`), CONSTRAINT `collection_rules_tenant_id_fkey` FOREIGN KEY (`tenant_id`) REFERENCES `tenants`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

CREATE TABLE `debts` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `public_id` CHAR(36) NOT NULL, `tenant_id` BIGINT UNSIGNED NOT NULL, `unit_id` BIGINT UNSIGNED NULL, `origin_type` ENUM('APPOINTMENT', 'MANUAL') NOT NULL, `origin_appointment_id` BIGINT UNSIGNED NULL, `customer_id` BIGINT UNSIGNED NULL, `debtor_name` VARCHAR(160) NOT NULL, `debtor_whatsapp` VARCHAR(20) NOT NULL, `debtor_email` VARCHAR(254) NULL, `debtor_document` VARCHAR(32) NULL, `description` VARCHAR(500) NOT NULL, `original_amount_cents` BIGINT UNSIGNED NOT NULL, `current_balance_cents` BIGINT UNSIGNED NOT NULL, `due_date` DATE NOT NULL, `status` ENUM('OPEN', 'COLLECTING', 'WAITING_RESPONSE', 'PROMISE_SCHEDULED', 'PIX_PENDING', 'PARTIALLY_PAID', 'PROMISE_OVERDUE', 'NEGOTIATING', 'DISPUTED', 'HUMAN_SUPPORT', 'PAUSED', 'PAID', 'CANCELED') NOT NULL DEFAULT 'OPEN', `collection_rule_id` BIGINT UNSIGNED NOT NULL, `collection_paused_at` DATETIME(3) NULL, `collection_paused_reason` VARCHAR(500) NULL, `human_support_at` DATETIME(3) NULL, `disputed_at` DATETIME(3) NULL, `paid_at` DATETIME(3) NULL, `canceled_at` DATETIME(3) NULL, `canceled_reason` VARCHAR(500) NULL, `notes` VARCHAR(1000) NULL, `created_by_user_id` BIGINT UNSIGNED NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), UNIQUE INDEX `debts_public_id_key` (`public_id`), INDEX `debts_tenant_id_status_due_date_idx` (`tenant_id`, `status`, `due_date`), INDEX `debts_tenant_id_debtor_whatsapp_idx` (`tenant_id`, `debtor_whatsapp`), INDEX `debts_tenant_id_customer_id_idx` (`tenant_id`, `customer_id`), INDEX `debts_tenant_id_origin_appointment_id_idx` (`tenant_id`, `origin_appointment_id`), INDEX `debts_tenant_id_collection_rule_id_status_idx` (`tenant_id`, `collection_rule_id`, `status`), CONSTRAINT `debts_tenant_id_fkey` FOREIGN KEY (`tenant_id`) REFERENCES `tenants`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE, CONSTRAINT `debts_unit_id_fkey` FOREIGN KEY (`unit_id`) REFERENCES `business_units`(`id`) ON DELETE SET NULL ON UPDATE CASCADE, CONSTRAINT `debts_origin_appointment_id_fkey` FOREIGN KEY (`origin_appointment_id`) REFERENCES `appointments`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE, CONSTRAINT `debts_customer_id_fkey` FOREIGN KEY (`customer_id`) REFERENCES `customers`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE, CONSTRAINT `debts_collection_rule_id_fkey` FOREIGN KEY (`collection_rule_id`) REFERENCES `collection_rules`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE, CONSTRAINT `debts_created_by_user_id_fkey` FOREIGN KEY (`created_by_user_id`) REFERENCES `users`(`id`) ON DELETE SET NULL ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

CREATE TABLE `debt_events` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `public_id` CHAR(36) NOT NULL, `tenant_id` BIGINT UNSIGNED NOT NULL, `debt_id` BIGINT UNSIGNED NOT NULL, `event_type` VARCHAR(40) NOT NULL, `metadata` JSON NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), UNIQUE INDEX `debt_events_public_id_key` (`public_id`), INDEX `debt_events_tenant_id_debt_id_created_at_idx` (`tenant_id`, `debt_id`, `created_at`), CONSTRAINT `debt_events_tenant_id_fkey` FOREIGN KEY (`tenant_id`) REFERENCES `tenants`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE, CONSTRAINT `debt_events_debt_id_fkey` FOREIGN KEY (`debt_id`) REFERENCES `debts`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
